-- UPS Ground Residential + FedEx-A + FedEx-B（含 Home Delivery）2026 价表
-- 数据源：2026年UPS&FedEx 报价表1.13.xlsx
-- 5 个新渠道：UPS-GROUND-US-RES / US-GROUND-FEDEX-A,B / US-HOMEDELIVERY-FEDEX-A,B
-- 总行数：UPS Res 1500 + FedEx-A Ground 1050 + Home Delivery 1050 + FedEx-B 同 = ~5700 行

DO $$
DECLARE
  v_card_id uuid;
  v_channel_id uuid;
  v_tenant_id uuid := (SELECT id FROM tenants LIMIT 1);
BEGIN

  -- ═══ UPS-GROUND-US-RES ═══
  -- 1) UPSERT channel
  INSERT INTO channels (tenant_id, code, name, lane, last_mile_method, primary_uom)
    VALUES (v_tenant_id, 'UPS-GROUND-US-RES', 'UPS Ground (US 住宅)', 'US', 'GROUND', 'KG')
    ON CONFLICT (tenant_id, code) DO UPDATE SET name = EXCLUDED.name
    RETURNING id INTO v_channel_id;
  IF v_channel_id IS NULL THEN
    SELECT id INTO v_channel_id FROM channels WHERE tenant_id=v_tenant_id AND code='UPS-GROUND-US-RES';
  END IF;

  -- 2) UPSERT rate_card (AR, USD, v2026)
  SELECT id INTO v_card_id FROM rate_cards
   WHERE channel_id = v_channel_id AND side='AR' AND version='v2026';
  IF v_card_id IS NULL THEN
    INSERT INTO rate_cards (tenant_id, channel_id, side, version, effective_from, currency, status)
      VALUES (v_tenant_id, v_channel_id, 'AR', 'v2026', '2026-01-01', 'USD', 'ACTIVE')
      RETURNING id INTO v_card_id;
  END IF;

  -- 3) 清旧 line + 灌新 line
  DELETE FROM rate_card_lines WHERE rate_card_id = v_card_id;
