  -- ═══ US-GROUND-FEDEX-B ═══
  -- 1) UPSERT channel
  INSERT INTO channels (tenant_id, code, name, lane, last_mile_method, primary_uom)
    VALUES (v_tenant_id, 'US-GROUND-FEDEX-B', 'FedEx Ground 商业 B价', 'US', 'GROUND', 'KG')
    ON CONFLICT (tenant_id, code) DO UPDATE SET name = EXCLUDED.name
    RETURNING id INTO v_channel_id;
  IF v_channel_id IS NULL THEN
    SELECT id INTO v_channel_id FROM channels WHERE tenant_id=v_tenant_id AND code='US-GROUND-FEDEX-B';
  END IF;

  -- 2) UPSERT rate_card (AR, USD, v2026)
  SELECT id INTO v_card_id FROM rate_cards
   WHERE channel_id = v_channel_id AND side='AR' AND version='v2026';
  IF v_card_id IS NULL THEN
    INSERT INTO rate_cards (tenant_id, channel_id, side, version, effective_from, currency, status)
      VALUES (v_tenant_id, v_channel_id, 'AR', 'v2026', '2026-01-01', 'USD', 'ACTIVE')
      RETURNING id INTO v_card_id;
  END IF;

